/* ★ 非卡片层（作业题面 / 作业列表 / 100 Days / 视频目录）：
   结构化定位走 asContextLayer；作业题面额外把**题面和用户正在写的代码**给模型 ——
   问"这题错在哪"时最需要的就是这两样，而不是底下那张讲义的片段。 */
var _l = null;
try{ _l = asContextLayer(); }catch(e){ _l = null; }
if (_l && _l.ctx){
  var lc = _l.ctx, lnotes = "";
  if (lc.problem){
    var ps = [String(lc.problem.statement_md || "").slice(0, AS_NOTES_MAX)];
    try{
      var mine = String((testState() || {}).code || "");
      if (mine.trim()) ps.push("\n\n【我现在写的代码】\n```python\n" + mine.slice(0, 2000) + "\n```");
    }catch(e){}
    lnotes = ps.join("").slice(0, AS_NOTES_MAX);
  }
  return Promise.resolve({
    chapter: lc.chapter, section: lc.section,
    point: lc.point || lc.section,
    notes: lnotes, screen: scr, tutor: tut
  });
}
var base = asContextPoint();
